-- View definitions for glut_ews.duckdb (schema: views).
-- Re-applied by scripts/rebuild_db.py on every rebuild. Edit here, never in the database directly.

-- main_centre
CREATE OR REPLACE VIEW "views".main_centre AS SELECT district, economic_centre FROM core.bridge_district_centre QUALIFY (row_number() OVER (PARTITION BY district ORDER BY weight DESC) = 1);

-- weather_weekly_district
CREATE OR REPLACE VIEW "views".weather_weekly_district AS SELECT district, "year"(date) AS "year", least(52, (CAST(floor(((dayofyear(date) - 1) / 7)) AS INTEGER) + 1)) AS "week", sum(rainfall_mm) AS rainfall_mm, avg(temp_mean_c) AS temp_mean_c FROM core.weather_daily GROUP BY ALL;

-- weather_season_district
CREATE OR REPLACE VIEW "views".weather_season_district AS SELECT s.season, w.district, sum(w.rainfall_mm) AS season_rainfall_mm, sum(CASE  WHEN ((w.rainfall_mm >= 1)) THEN (1) ELSE 0 END) AS rain_days, sum(CASE  WHEN ((w.rainfall_mm >= 50)) THEN (1) ELSE 0 END) AS heavy_rain_days, avg(w.temp_mean_c) AS temp_mean_c, avg(w.temp_max_c) AS temp_max_c, sum(w.et0_mm) AS et0_mm FROM core.dim_season AS s INNER JOIN core.weather_daily AS w ON ((w.date BETWEEN s.season_start AND s.season_end)) GROUP BY ALL;

-- preseason_rain_district
CREATE OR REPLACE VIEW "views".preseason_rain_district AS SELECT s.season, w.district, sum(w.rainfall_mm) AS preseason_rainfall_mm FROM core.dim_season AS s INNER JOIN core.weather_daily AS w ON (((w.date >= (s.season_start - to_months(CAST(trunc(CAST(3 AS DOUBLE)) AS INTEGER)))) AND (w.date < s.season_start))) GROUP BY ALL;

-- harvest_market_season
CREATE OR REPLACE VIEW "views".harvest_market_season AS SELECT c.harvest_of_season AS season, p.economic_centre, p.crop, avg(p.wholesale_price_rs_kg) AS harvest_wholesale_mean_rs_kg, min(p.wholesale_price_rs_kg) AS harvest_wholesale_min_rs_kg, max(p.wholesale_price_rs_kg) AS harvest_wholesale_max_rs_kg, avg(p.retail_price_rs_kg) AS harvest_retail_mean_rs_kg, sum(a.arrivals_t) AS market_arrivals_t, sum(a.wastage_t) AS market_wastage_t FROM core.market_prices_weekly AS p INNER JOIN core.market_arrivals_weekly AS a USING (week_start_date, economic_centre, crop) INNER JOIN core.dim_calendar AS c USING (week_start_date) WHERE (c.harvest_of_season IS NOT NULL) GROUP BY ALL;

-- component1_dataset
CREATE OR REPLACE VIEW "views".component1_dataset AS WITH cw AS (SELECT b.economic_centre, w."year", w."week", (sum((w.rainfall_mm * b.weight)) / sum(b.weight)) AS rainfall_mm, (sum((w.temp_mean_c * b.weight)) / sum(b.weight)) AS temperature_c FROM "views".weather_weekly_district AS w INNER JOIN core.bridge_district_centre AS b USING (district) GROUP BY ALL)SELECT c."year", c."week", c.week_start_date, c.season, c.season_type, p.economic_centre, p.crop, p.wholesale_price_rs_kg, p.retail_price_rs_kg, m.ccpi_2021_100 AS ccpi, a.arrivals_t AS market_arrivals_t, a.wastage_t AS market_wastage_t, n.extent_ha AS season_extent_ha, n.production_t AS season_production_t, round(cw.rainfall_mm, 1) AS rainfall_mm, round(cw.temperature_c, 2) AS temperature_c FROM core.market_prices_weekly AS p INNER JOIN core.market_arrivals_weekly AS a USING (week_start_date, economic_centre, crop) INNER JOIN core.dim_calendar AS c USING (week_start_date) LEFT JOIN core.macro_monthly AS m ON ((m."month" = strftime(c.week_start_date, '%Y-%m'))) LEFT JOIN core.national_supply_season AS n ON (((n.season = c.season) AND (n.crop = p.crop))) LEFT JOIN cw ON (((cw.economic_centre = p.economic_centre) AND (cw."year" = c."year") AND (cw."week" = c."week")));

-- season_base
CREATE OR REPLACE VIEW "views".season_base AS SELECT s.season, d.season_type, d.season_year, s.district, mc.economic_centre, s.crop, s.extent_ha AS cultivated_extent_ha, t.target_ha AS target_extent_ha, s.production_t, s.yield_t_ha, k.farmgate_rs_kg AS farmgate_price_rs_kg, k.unit_cost_rs_kg, h.harvest_wholesale_mean_rs_kg, h.harvest_wholesale_min_rs_kg, h.harvest_wholesale_max_rs_kg, h.harvest_retail_mean_rs_kg, h.market_arrivals_t, h.market_wastage_t, w.season_rainfall_mm, pr.preseason_rainfall_mm, w.rain_days, w.heavy_rain_days, w.temp_mean_c, w.temp_max_c, w.et0_mm, g.historical_glut_label, g.cobweb_index, p2.supply_pressure_score, l.glut_risk_label, dd.climatic_zone, dd.elevation_m, n.production_t AS national_production_t, d.split FROM core.supply_season AS s INNER JOIN core.dim_season AS d USING (season) INNER JOIN core.dim_district AS dd USING (district) INNER JOIN "views".main_centre AS mc USING (district) INNER JOIN core.planting_target_season AS t USING (season, district, crop) INNER JOIN core.cost_season AS k USING (season, crop) INNER JOIN core.national_supply_season AS n USING (season, crop) LEFT JOIN "views".harvest_market_season AS h ON (((h.season = s.season) AND (h.economic_centre = mc.economic_centre) AND (h.crop = s.crop))) LEFT JOIN "views".weather_season_district AS w USING (season, district) LEFT JOIN "views".preseason_rain_district AS pr USING (season, district) LEFT JOIN outputs.c1_glut_season AS g ON (((g.season = s.season) AND (g.economic_centre = mc.economic_centre) AND (g.crop = s.crop))) LEFT JOIN outputs.c2_pressure_score AS p2 USING (season, district, crop) LEFT JOIN outputs.c3_training_label AS l USING (season, district, crop);

-- component2_dataset
CREATE OR REPLACE VIEW "views".component2_dataset AS SELECT season, season_type, season_year, district, economic_centre, crop, cultivated_extent_ha, target_extent_ha, production_t, yield_t_ha, farmgate_price_rs_kg, unit_cost_rs_kg, harvest_wholesale_mean_rs_kg AS harvest_wholesale_price_rs_kg, market_arrivals_t, season_rainfall_mm, preseason_rainfall_mm, rain_days, heavy_rain_days, temp_mean_c, et0_mm, historical_glut_label, cobweb_index FROM "views".season_base;

-- component3_dataset
CREATE OR REPLACE VIEW "views".component3_dataset AS SELECT season, season_type, season_year, district, economic_centre, crop, cultivated_extent_ha, target_extent_ha, production_t, yield_t_ha, farmgate_price_rs_kg, unit_cost_rs_kg, harvest_wholesale_mean_rs_kg, harvest_wholesale_min_rs_kg, harvest_wholesale_max_rs_kg, harvest_retail_mean_rs_kg, market_arrivals_t, market_wastage_t, season_rainfall_mm, preseason_rainfall_mm, rain_days, heavy_rain_days, temp_mean_c, temp_max_c, historical_glut_label, cobweb_index, supply_pressure_score, glut_risk_label, split FROM "views".season_base;

-- component4_dataset
CREATE OR REPLACE VIEW "views".component4_dataset AS SELECT season, season_type, season_year, district, economic_centre, crop, climatic_zone, elevation_m, cultivated_extent_ha, sum(cultivated_extent_ha) OVER (PARTITION BY district, season) AS available_land_ha, target_extent_ha, production_t, yield_t_ha, farmgate_price_rs_kg, unit_cost_rs_kg, round(((unit_cost_rs_kg * yield_t_ha) * 1000), 0) AS cost_of_cultivation_rs_ha, national_production_t, market_arrivals_t, harvest_wholesale_mean_rs_kg AS harvest_wholesale_price_rs_kg, season_rainfall_mm, temp_mean_c, historical_glut_label, cobweb_index, supply_pressure_score, glut_risk_label FROM "views".season_base;
